const FILES = new Set<string>(FILES1 as string[]);
const label = (value: unknown): string => JSON.stringify(value).slice(0, 70);

describe('import-graph 벡터: 옛 TS가 낸 값', () => {
  it.each(EXTRACT.map((c) => [c.title, c]))('extractImportSpecifiers: %s', (_t, c) => {
    expect(JSON.stringify(extractImportSpecifiers(c.source))).toBe(c.expected);
  });
  it.each(EXTRACT.filter((c) => c.tokens !== undefined).map((c) => [c.title, c]))('tokenize: %s', (_t, c) => {
    expect(JSON.stringify(tokenize(c.source))).toBe(c.tokens);
  });
  it.each(PATHS.map((c) => [label(c.path), c]))('경로 판정: %s', (_t, c) => {
    expect(JSON.stringify([isPageFileInService(c.path), routeWrapperFolder(c.path) ?? null, isGraphSourceFile(c.path)])).toBe(c.expected);
  });
  it.each(NORMALIZE.map((c) => [label(c.path), c]))('normalizeServicePath: %s', (_t, c) => {
    expect(JSON.stringify(normalizeServicePath(c.path) ?? null)).toBe(c.expected);
  });
  it.each(JSONC.map((c) => [label(c.text), c]))('stripJsonc: %s', (_t, c) => {
    expect(stripJsonc(c.text)).toBe(c.expected);
  });
  it.each(EXTENDSPATH.map((c) => [label([c.text, c.dir]), c]))('tsconfigExtendsPath: %s', (_t, c) => {
    expect(JSON.stringify(tsconfigExtendsPath(c.text, c.dir) ?? null)).toBe(c.expected);
  });
  it.each(ALIAS.map((c) => [label([c.text, c.dir, c.base]), c]))('parseAliasConfig(키 순서 포함): %s', (_t, c) => {
    expect(JSON.stringify(parseAliasConfig(c.text, c.dir, c.base))).toBe(c.expected);
  });
  it.each(RESOLVE.map((c) => [label([c.spec, c.from, c.alias]), c]))('resolveImport: %s', (_t, c) => {
    expect(JSON.stringify(resolveImport(c.spec, c.from, FILES, c.alias) ?? null)).toBe(c.expected);
  });
  it.each(REVERSE.map((c) => [label(c.sources), c]))('buildReverseGraph(넣은 순서 포함): %s', (_t, c) => {
    const graph = buildReverseGraph(new Map<string, string>(c.sources), new Set<string>(c.files), c.alias);
    expect(JSON.stringify([...graph].map(([k, v]) => [k, [...v]]))).toBe(c.expected);
  });
  // oldOrder가 있는 사례는 순서만 옛 TS(localeCompare)와 다르다: 후보 집합은 같고 순서는 UTF-16 코드 단위 순서다
  it.each(TRACE.map((c) => [c.title, c]))('tracePages: %s', (_t, c) => {
    const reverse = new Map<string, Set<string>>(c.reverse.map(([k, v]: [string, string[]]) => [k, new Set(v)]));
    const maxDepth = c.maxDepth === 'NaN' ? Number.NaN : c.maxDepth === 'Infinity' ? Number.POSITIVE_INFINITY : (c.maxDepth as number);
    const actual = tracePages(c.changed, reverse, new Set<string>(c.files), maxDepth);
    expect(JSON.stringify(actual)).toBe(c.expected);
    if (c.oldOrder !== undefined) {
      const key = (r: { candidates: unknown[] }) => r.candidates.map((x) => JSON.stringify(x)).sort();
      expect(key(actual), '후보 집합은 옛 TS와 같다').toEqual(key(JSON.parse(c.oldOrder)));
    }
  });
});
